"""Author fresh multi-turn checks separately from the training variants."""
import json
from pathlib import Path
R=Path(__file__).resolve().parent
prior=[json.loads(x) for x in (R.parent/'requirements-draft-v19/acquisition.jsonl').read_text().splitlines()]
systems={t:next(x['messages'][0]['content'] for x in prior if x['task']==t) for t in ['draft','bounds']}
rows=[]
def add(id,turns,desc,title,questions=None,literals=None):
 assert len(turns)%2==1
 m=[{'role':'system','content':systems['draft']}]+[{'role':'user' if i%2==0 else 'assistant','content':x} for i,x in enumerate(turns)]
 m.append({'role':'assistant','content':json.dumps({'summary':title,'description':desc,'questions':questions or []},ensure_ascii=False)})
 row={'id':id,'task':'draft','messages':m}
 if literals:row['required_literals']=literals
 rows.append(row)
add('draft-payment',['Можно переслать платёжку подрядчику; там код заявки и сумма.','Код исправляем?','Нужен код договора вместо кода заявки.','Отправлять после исправления?','Передумал: разрешение на пересылку снимаю.','Сумму удаляем вместе с разрешением?','Сумма нужна, правка кода тоже.','Как оформить результат?','Как черновик, без отправки. Составь задачу.'],'Сохранить черновик платёжки с кодом договора вместо кода заявки и суммой. Подрядчику не пересылать: разрешение отозвано.','Черновик платёжки')
add('draft-copies',['Две одинаковые схемы — для геодезиста и прораба. Разрешаю только подготовку.','Обе схемы передать адресатам?','Даю согласие передать геодезисту. Прорабу пока нельзя.','Прорабу добавить пояснения?','Схемы должны остаться одинаковыми.','Передачу геодезисту отменяем?','Не отменяем. Зафиксируй решения.'],'Подготовить одинаковые схемы для геодезиста и прораба без дополнительных пояснений. Геодезисту передача разрешена; прорабу не передавать.','Две схемы')
