(R/'fresh-drafts.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows))
checks=[]
for i,n in enumerate([-83,-54,11,47,96]):
 for kind in ['equal','lower','upper','open']:
  state={'status':'open' if kind=='open' else 'final','lower':n if kind in ['equal','lower'] else None,'upper':n if kind in ['equal','upper'] else None,'lowerInclusive':True if kind=='equal' else False if kind=='lower' else None,'upperInclusive':True if kind in ['equal','upper'] else None}
  text={'equal':f'Для новой сверки окончательно принято ровно {n}.','lower':f'Для новой сверки окончательно принято строго больше {n}.','upper':f'Для новой сверки окончательно принято не больше {n}.','open':f'В новой сверке {n} лишь обсуждают, утверждённого значения нет.'}[kind]
  checks.append({'id':f'numeric-{i}-{kind}','task':'bounds','messages':[{'role':'system','content':systems['bounds']},{'role':'user','content':text},{'role':'assistant','content':json.dumps(state)}]})
for i,values in enumerate([[-87,-19,-51,-19],[-92,-31,-68,-31],[-79,-22,-47,-22],[-101,-16,-58,-16],[-66,-13,-39,-13],[-95,-24,-72,-24]]):
 for reverse in [False,True]:
  for style in [0,1]:
   seq=', '.join(map(str,values));direction=('убыванию' if reverse else 'возрастанию') if not style else ('большего к меньшему' if reverse else 'меньшего к большему')
   text=f'Список для новой сверки: {seq}. Отсортируй по {direction}. Ответ — JSON-массив.' if not style else f'Проверяем значения {seq}. Расположи от {direction}, не убирая повторов. Верни JSON-массив.'
   checks.append({'id':f'sort-{i}-{int(reverse)}-{style}','task':'general','messages':[{'role':'user','content':text},{'role':'assistant','content':json.dumps(sorted(values,reverse=reverse))}]})
for i,(prompt,answer) in enumerate([('Только число: сколько граней имеет обычный куб?',6),('Для контрольного расчёта умножь 26 на 7. Только число.',182),('Только число: сколько сторон у обычного треугольника?',3),('Только число: сколько минут в одном часе?',60)]):
 checks.append({'id':f'general-{i}','task':'general','messages':[{'role':'user','content':prompt},{'role':'assistant','content':json.dumps(answer,ensure_ascii=False)}]})
assert len(checks)==48
(R/'check.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in checks))
print('Reserved 20 authored drafts and 48 numeric/sort/general checks.')
